 "content": "from collections import Counter, deque


def transform(grid):
    """Connect repeated non-dominant solid-square tile markers along rows/columns."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    markers = []

    # A tile's signal is a solid square component (a single pixel in some
    # tasks, a small solid patch in others); enclosing tile frames are rings.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            hh, ww = max(ys)-min(ys)+1, max(xs)-min(xs)+1
            side = hh
            if hh == ww and len(cells) == side * side:
                markers.append((color, (min(ys)+max(ys))//2, (min(xs)+max(xs))//2))

    if not markers:
        return out

    # The ordinary tile fill is the most frequent signal; exceptional colors
    # are the ones whose matching markers are linked.
    counts = Counter(color for color, _, _ in markers)
    ordinary = counts.most_common(1)[0][0]
    by_color = {}
    for color, r, c in markers:
        if color != ordinary:
            by_color.setdefault(color, []).append((r, c))

    for color, points in by_color.items():
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i+1:]:
                if r1 == r2:
                    lo, hi = sorted((c1, c2))
                    for c in range(lo+1, hi):
                        if out[r1][c] == 0:
                            out[r1][c] = color
                elif c1 == c2:
                    lo, hi = sorted((r1, r2))
                    for r in range(lo+1, hi):
                        if out[r][c1] == 0:
                            out[r][c1] = color
    return out
