from collections import Counter, deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    patches = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            ys = [p[0] for p in cells]; xs = [p[1] for p in cells]
            y0,y1,x0,x1 = min(ys),max(ys),min(xs),max(xs)
            # Colored solid square tile centers; skip outlines and other shapes.
            if len(cells) == (y1-y0+1)*(x1-x0+1) and y1-y0 == x1-x0:
                patches.append((color,y0,y1,x0,x1))
    if not patches:
        return out
    counts = Counter(p[0] for p in patches)
    common, common_count = counts.most_common(1)[0]
    # The most frequent tile-center color is the ordinary/background marker;
    # connect only the other colors (also when the counts are tied at half).
    patches = [p for p in patches if p[0] != common]
    for i, (color,y0,y1,x0,x1) in enumerate(patches):
        for color2,yy0,yy1,xx0,xx1 in patches[i+1:]:
            if color != color2:
                continue
            if y0 == yy0 and y1 == yy1:
                left_end, right_start = (x1, xx0) if x1 < xx0 else (xx1, x0)
                for y in range(y0,y1+1):
                    for x in range(left_end+1,right_start):
                        if out[y][x] == 0: out[y][x] = color
            elif x0 == xx0 and x1 == xx1:
                top_end, bottom_start = (y1, yy0) if y1 < yy0 else (yy1, y0)
                for x in range(x0,x1+1):
                    for y in range(top_end+1,bottom_start):
                        if out[y][x] == 0: out[y][x] = color
    return out

