def transform(grid):
    """Join aligned non-background square markers through blank cells."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    patches = []

    # Find solid square components (the colored centers of the repeated tiles).
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            y0 = min(y for y, _ in cells)
            y1 = max(y for y, _ in cells)
            x0 = min(x for _, x in cells)
            x1 = max(x for _, x in cells)
            side = y1 - y0 + 1
            if side == x1 - x0 + 1 and len(cells) == side * side:
                patches.append((color, y0, y1, x0, x1))

    if not patches:
        return out

    # A clipped border fragment can look like a tiny square; retain only the
    # marker scale when larger square patches are present.
    marker_side = max(y1 - y0 + 1 for _, y0, y1, _, _ in patches)
    patches = [p for p in patches if p[2] - p[1] + 1 == marker_side]
    counts = Counter(p[0] for p in patches)
    background = counts.most_common(1)[0][0]
    patches = [p for p in patches if p[0] != background]

    # Connect equal-colored, collinear markers. The line follows the center
    # row/column(s) of the square and colors only blank cells, preserving tiles.
    for i, (color, y0, y1, x0, x1) in enumerate(patches):
        for other_color, yy0, yy1, xx0, xx1 in patches[i + 1:]:
            if color != other_color:
                continue
            if y0 == yy0 and y1 == yy1:
                left_end, right_start = (x1, xx0) if x1 < xx0 else (xx1, x0)
                side = y1 - y0 + 1
                center_rows = range(y0 + (side - 1) // 2, y0 + side // 2 + 1)
                for y in center_rows:
                    for x in range(left_end + 1, right_start):
                        if out[y][x] == 0:
